      en: ["Sēlija region", "Near Daugavpils", "Southeastern Latvia", "Population approx. 2,000"],
      es: ["Región de Selonia", "Cerca de Daugavpils", "Sureste de Letonia", "Población aprox. 2.000"],
      pt: ["Região da Selônia", "Perto de Daugavpils", "Sudeste da Letónia", "População aprox. 2.000"],
      fr: ["Région de Sélonie", "Près de Daugavpils", "Sud-est de la Lettonie", "Population env. 2 000"],
