    imageHint: "Varakļāni manor house",
    descriptionAdvanced: {
      de: "Varakļāni ist eine Kleinstadt im Osten Lettlands, die für ihr bedeutendes kulturelles Erbe bekannt ist. Das Herzstück der Stadt ist das Schloss Varakļāni, ein prächtiger klassizistischer Bau, der zwischen 1783 und 1789 für den Grafen Michael Jan Borch errichtet wurde. Das Schloss beherbergt heute ein Museum und ist von einem weitläufigen Park mit dem geheimnisvollen Liebesstein umgeben. Varakļāni war historisch ein bedeutendes Zentrum für das jüdische Leben in der Region, wovon heute noch der alte jüdische Friedhof zeugt. Die katholische Mariä Himmelfahrt Kirche aus dem 19. Jahrhundert ist ein weiteres architektonisches Highlight der Stadt. Geografisch liegt Varakļāni am Übergang zwischen den Regionen Vidzeme und Latgale, was der Stadt eine besondere kulturelle Identität verleiht. Die Wirtschaft ist heute hauptsächlich von der Landwirtschaft und dem Kleingewerbe geprägt.",
      hu: "Varakļāni városa Lettország keleti részén található, és gazdag nemesi örökségéről híres. A település legjelentősebb műemléke a Varakļāni-kastély, amelyet Michael Jan Borch gróf építtetett 1783 és 1789 között klasszicista stílusban. A kastélyhoz egy hatalmas angolpark tartozik, ahol a híres „Szerelem-szikla” is található. A város történelmileg fontos vallási központ is, amit az 1854-ben felszentelt római katolikus templom és az egykori zsidó közösség emlékei igazolnak. Varakļāni elhelyezkedése Latgale és Vidzeme régiók határán egyedi kulturális keveredést eredményezett az évszázadok során. A város ma a Varakļāni község központja, ahol a helyi múzeum aktívan gondozza a Borch család és a régió történeti emlékeit. A gazdaság pillérei a mezőgazdaság, az erdőgazdálkodás és a helyi szolgáltatások.",
      ro: "Varakļāni este un oraș mic din estul Letoniei, renumit pentru moștenirea sa nobiliară și arhitectura istorică. Punctul central de atracție este Castelul Varakļāni, un palat construit în stil clasicist între anii 1783 și 1789 pentru contele Michael Jan Borch. Castelul este înconjurat de un parc vast amenajat în stil englezesc, care adăpostește misterioasa „Piatră a Iubirii”. Din punct de vedere istoric, Varakļāni a fost un centru cultural și religios important, având o biserică romano-catolică impresionantă ridicată la mijlocul secolului al XIX-lea. Orașul este situat la limita dintre regiunile Vidzeme și Latgale, îmbinând tradițiile specifice ambelor zone. Muzeul local din incinta castelului oferă informații detaliate despre dinastia Borch și istoria locală. Astăzi, economia orașului se bazează în principal pe agricultură și întreprinderi mici de prelucrare a lemnului.",
      en: "Varakļāni is a town in eastern Latvia, celebrated for its rich aristocratic history and architectural landmarks. The town's primary attraction is the Varakļāni Palace, a neoclassical residence built between 1783 and 1789 for Count Michael Jan Borch. The palace is nestled within an expansive English-style landscape park, which features the legendary 'Stone of Love.' Historically, Varakļāni was a significant center for both the Catholic faith and the Jewish community, with the 19th-century Assumption of the Virgin Mary Church remaining a key spiritual site. Geographically located on the border between the Vidzeme and Latgale regions, the town possesses a unique cultural blend. Today, it serves as the administrative center of the Varakļāni Municipality, with its museum preserving the legacy of the Borch family and regional history.",
      es: "Varakļāni es una pequeña ciudad en el este de Letonia, conocida por su importante patrimonio cultural. El corazón de la ciudad es el castillo de Varakļāni, un magnífico edificio clasicista construido entre 1783 y 1789 para el conde Michael Jan Borch. El castillo alberga hoy un museo y está rodeado por un extenso parque con la misteriosa 'Piedra del Amor'. Varakļāni fue históricamente un centro importante para la vida judía en la región, de lo cual todavía hoy es testigo el antiguo cementerio judío. La iglesia católica de la Asunción de María, del siglo XIX, es otro punto arquitectónico destacado de la ciudad. Geográficamente, Varakļāni se encuentra en la transición entre las regiones de Vidzeme y Latgale, lo que le da a la ciudad una identidad cultural especial. La economía está hoy marcada principalmente por la agricultura y los pequeños negocios.",
      pt: "Varakļāni é uma pequena cidade no leste da Letónia, conhecida pelo seu importante património cultural. O coração da cidade é o castelo de Varakļāni, um magnífico edifício classicista construído entre 1783 e 1789 para o conde Michael Jan Borch. O castelo abriga hoje um museu e está rodeado por um extenso parque com a misteriosa 'Pedra do Amor'. Varakļāni foi historicamente um centro importante para a vida judaica na região, do qual o antigo cemitério judaico ainda é testemunha hoje. A igreja católica da Assunção de Maria, do século XIX, é outro destaque arquitetónico da cidade. Geograficamente, Varakļāni situa-se na transição entre as regiões de Vidzeme e Latgale, o que confere à cidade uma identidade cultural especial. A economia é hoje marcada principalmente pela agricultura e pelo pequeno comércio.",
      fr: "Varakļāni est une petite ville de l'est de la Lettonie, réputée pour son important patrimoine culturel. Le cœur de la ville est le château de Varakļāni, un magnifique édifice néo-classique érigé entre 1783 et 1789 pour le comte Michael Jan Borch. Le château abrite aujourd'hui un musée et est entouré d'un vaste parc recelant la mystérieuse 'Pierre de l'Amour'. Historiquement, Varakļāni était un centre majeur de la vie juive dans la région, ce dont témoigne encore l'ancien cimetière juif. L'église catholique de l'Assomption de Marie, datant du XIXe siècle, constitue un autre joyau architectural de la ville. Géographiquement, Varakļāni se trouve à la jonction entre les régions de Vidzeme et Latgale, ce qui lui confère une identité culturelle particulière. L'économie actuelle repose principalement sur l'agriculture et le petit artisanat.",
    },
