      hu: ["A Varakļāni-kastély építése 1783-ban kezdődött Michael Jan Borch gróf parancsára.", "A település 1928-ban nyerte el hivatalosan a városi rangot.", "A kastélypark Lettország egyik legnagyobb és legszebb történeti kertje.", "A helyi római katolikus templomot 1854-ben szentelték fel.", "Varakļāni történelmileg a Borch grófi család magánbirtoka volt.", "A város a Kažova folyó partján helyezkedik el."],
