      en: ["Varakļāni Palace was constructed between 1783 and 1789.", "The town was granted official town rights in the year 1928.", "The palace park is one of the most significant historical parks in Latvia.", "The local Roman Catholic church was completed and consecrated in 1854.", "Varakļāni was the ancestral estate of the influential Borch family.", "The town is situated on the banks of the Kažova River."],
