      en: ["First mentioned in historical documents in 1230.", "The stone bridge over the Abava was completed in 1873.", "Granted official town rights in 1917.", "Features ruins of a 13th-century Livonian Order castle.", "Known as the 'Switzerland of Courland' for its hills.", "The coat of arms depicts an oak branch with three acorns."],
      es: ["Primera mención documental en el año 1230.", "El puente de piedra sobre el Abava fue construido en 1873.", "Recibió oficialmente los derechos de ciudad en el año 1917.", "Alberga las ruinas de un castillo de la Orden Teutónica del siglo XIII.", "A menudo se le llama la 'Suiza de Curlandia' por su paisaje.", "El escudo de la ciudad muestra una rama de roble con tres bellotas."],
      pt: ["Primeira menção documental no ano 1230.", "A ponte de pedra sobre o Abava foi construída em 1873.", "Recebeu oficialmente direitos de cidade no ano 1917.", "Abriga as ruínas de um castelo da Ordem Teutónica do século XIII.", "É frequentemente chamada de 'Suíça da Curlândia' devido à paisagem.", "O brasão da cidade mostra um ramo de carvalho com três bolotas."],
      fr: ["Première mention documentée en l'an 1230.", "Le pont de pierre sur l'Abava a été construit en 1873.", "A reçu officiellement le statut de ville en 1917.", "Abrite les ruines d'un château de l'Ordre Teutonique du XIIIe siècle.", "Souvent surnommée la 'Suisse courlandaise' en raison du paysage.", "Les armoiries de la ville représentent une branche de chêne avec trois glands."],
