      en: ["First documented in historical records in 1483.", "The Swedish Gate was constructed in 1688.", "Awarded official town rights in 1928.", "Home to a military cemetery with over 23,000 graves.", "Located approximately 14 km from the Lithuanian border.", "Nearly completely destroyed during battles in 1944."],
      es: ["Primera mención del lugar en 1483.", "La Puerta Sueca fue construida en 1688.", "Recibió los derechos de ciudad en 1928.", "Alberga un cementerio con más de 23.000 soldados caídos.", "Se encuentra a solo 14 km de la frontera con Lituania.", "Fue destruida casi por completo en la Segunda Guerra Mundial."],
      pt: ["Primeira menção ao local em 1483.", "A Porta Sueca foi construída em 1688.", "Recebeu direitos de cidade em 1928.", "Abriga um cemitério com mais de 23.000 soldados mortos.", "Localiza-se a apenas 14 km da fronteira com a Lituânia.", "Foi quase totalmente destruída na Segunda Guerra Mundial."],
      fr: ["Première mention du lieu en 1483.", "La Porte Suédoise a été construite en 1688.", "A obtenu le statut de ville en 1928.", "Abrite un cimetière de plus de 23 000 soldats tombés au combat.", "Située à seulement 14 km de la frontière avec la Lituanie.", "A été presque entièrement détruite pendant la Seconde Guerre mondiale."],
