      en: ["The Battle of Durbe took place on July 13, 1260.", "First documented in historical records in 1263.", "Official town rights were granted in 1893.", "Recognized as Latvia's smallest town by population.", "The local Lutheran church was built in 1651.", "Nearby Lake Durbe covers 6.7 square kilometers."],
      es: ["La batalla de Durbe tuvo lugar el 13 de julio de 1260.", "Primera mención escrita en el año 1263.", "Los derechos de ciudad fueron otorgados en 1893.", "La ciudad más pequeña de Letonia con unos 500 habitantes.", "La iglesia luterana fue construida en 1651.", "El cercano lago Durbe tiene una superficie de 6,7 km²."],
      pt: ["A batalha de Durbe ocorreu em 13 de julho de 1260.", "Primeira menção escrita no ano de 1263.", "Os direitos de cidade foram concedidos em 1893.", "A cidade mais pequena da Letónia com cerca de 500 habitantes.", "A igreja luterana foi construída em 1651.", "O vizinho lago Durbe tem uma área de 6,7 km²."],
      fr: ["La bataille de Durbe a eu lieu le 13 juillet 1260.", "Première mention écrite en 1263.", "Le statut de ville a été accordé en 1893.", "Plus petite ville de Lettonie avec environ 500 habitants.", "L'église luthérienne a été érigée en 1651.", "Le lac Durbe, situé à proximité, s'étend sur 6,7 km²."],
