      ro: ["Conacul Eleja a fost construit între anii 1806-1810.", "Clădirea principală a fost distrusă în 1915, în Primul Război Mondial.", "Pavilionul ceaiului (Tea House) a fost restaurat în 2016.", "Este situat pe autostrada internațională A8 (Riga-Šiauliai).", "Face parte administrativ din municipalitatea Jelgava.", "Contele Jeannot Medem a fost ctitorul reședinței."],
      en: ["Eleja Manor was constructed between 1806 and 1810.", "The main manor house was destroyed during WWI in 1915.", "The restored Tea House was opened to the public in 2016.", "Located on the primary A8 highway (Riga-Šiauliai).", "Part of the Jelgava administrative municipality.", "Count Jeannot Medem commissioned the building of the manor."],
      es: ["La mansión Eleja fue construida entre 1806 y 1810.", "Destrucción de la casa principal en la Primera Guerra Mundial en 1915.", "El pabellón de té fue restaurado en el año 2016.", "Se encuentra en la carretera estratégica A8 (Riga-Šiauliai).", "Pertenece administrativamente al distrito de Jelgava.", "El conde Jeannot Medem fue el promotor del palacio."],
      pt: ["A mansão Eleja foi construída entre 1806 e 1810.", "Destruição da casa principal na Primeira Guerra Mundial em 1915.", "O pavilhão de chá foi restaurado no ano de 2016.", "Situa-se na estrada estratégica A8 (Riga-Šiauliai).", "Pertence administrativamente ao distrito de Jelgava.", "O conde Jeannot Medem foi o promotor do palácio."],
