      es: ["El castillo de madera semigaliano fue mencionado en el siglo XIII.", "El parque natural de Tērvete fue fundado en el año 1958.", "Museo de la escritora Anna Brigadere (Sprīdīši).", "El parque abarca una superficie de más de 1.200 hectáreas.", "La reconstrucción de madera del castillo muestra técnicas de construcción antiguas.", "Famoso por la cerveza 'Tērvete' producida localmente."],
      pt: ["O castelo de madeira semigaliano foi mencionado no século XIII.", "O Parque Natural de Tērvete foi fundado no ano de 1958.", "Museu da escritora Anna Brigadere (Sprīdīši).", "O parque abrange uma área de mais de 1.200 hectares.", "A reconstrução de madeira do castelo mostra a arte de construção antiga.", "Famoso pela cerveja 'Tērvete' produzida localmente."],
