      ro: ["Kursīši se află la aproximativ 20 de kilometri sud de orașul Saldus.", "Conacul Kursīši a fost stabilit inițial în secolul al XVII-lea.", "Aproximativ 40% din teritoriul parohiei este acoperit de păduri.", "Râul Bruzile traversează parohia, oferind un peisaj pitoresc.", "Populația actuală a localității Kursīši este de aproximativ 350 de locuitori.", "Granița cu Lituania se află la mai puțin de 10 kilometri distanță."],
      en: ["Kursīši is located about 20 kilometers south of the town of Saldus.", "The Kursīši Manor was established during the 17th century.", "Approximately 40% of the parish territory is covered by forests.", "The Bruzile River flows directly through the administrative area of Kursīši.", "The population of the Kursīši parish is around 350 residents.", "The Lithuanian border is less than 10 kilometers away from the village."],
      es: ["Kursīši se encuentra a unos 20 kilómetros al sur de la ciudad de Saldus.", "La finca Kursīši fue fundada en el siglo XVII.", "Aproximadamente el 40 % de la superficie del municipio está cubierta de bosques.", "El río Bruzile fluye directamente a través del área administrativa de Kursīši.", "La población del municipio es de unas 350 personas.", "La frontera lituana está a menos de 10 kilómetros del pueblo."],
      pt: ["Kursīši fica a cerca de 20 quilómetros a sul da cidade de Saldus.", "A herdade Kursīši foi fundada no século XVII.", "Cerca de 40 % da área do município é coberta por florestas.", "O rio Bruzile corre diretamente através da área administrativa de Kursīši.", "A população do município é de cerca de 350 pessoas.", "A fronteira lituana fica a menos de 10 quilómetros da aldeia."],
      fr: ["Kursīši est situé à environ 20 kilomètres au sud de la ville de Saldus.", "Le domaine de Kursīši a été fondé au XVIIe siècle.", "Environ 40 % de la superficie de la commune est recouverte de forêts.", "La rivière Bruzile traverse directement la zone administrative de Kursīši.", "La population de la commune est d'environ 350 habitants.", "La frontière lituanienne se trouve à moins de 10 kilomètres du village."],
