      ro: ["Nīca este faimoasă pentru cel mai colorat costum popular din Letonia.", "Biserica luterană din Nīca a fost sfințită în anul 1851.", "Parcul Natural Bernāti se învecinează direct cu teritoriul localității.", "Pescuitul a fost principala sursă de venit încă din secolul al XVI-lea.", "Lacul Liepāja este situat imediat la nord de așezare.", "În apropiere se află unele dintre cele mai înalte dune de coastă din Letonia."],
      en: ["Nīca is famous for having the most colorful folk costumes in Latvia.", "The Nīca Lutheran Church was consecrated in the year 1851.", "The Bernāti Nature Park directly borders the Nīca administrative area.", "Fishing has been a primary source of income since the 16th century.", "Lake Liepāja is situated immediately to the north of the settlement.", "The area features some of the highest coastal dunes in Latvia."],
      es: ["Nīca es famosa por el traje típico más colorido de Letonia.", "La iglesia luterana de Nīca fue consagrada en el año 1851.", "El Parque Natural de Bernāti limita directamente con el territorio de Nīca.", "La pesca fue la principal fuente de ingresos desde el siglo XVI.", "El lago de Liepāja (Liepājas ezers) se encuentra inmediatamente al norte del lugar.", "Cerca se encuentran algunas de las dunas costeras más altas de Letonia."],
      pt: ["Nīca é famosa pelo traje típico mais colorido da Letónia.", "A igreja luterana de Nīca foi consagrada no ano 1851.", "O Parque Natural de Bernāti confina diretamente com o território de Nīca.", "A pesca foi a principal fonte de rendimento desde o século XVI.", "O lago de Liepāja (Liepājas ezers) situa-se imediatamente a norte do local.", "Nas proximidades encontram-se algumas das dunas costeiras mais altas da Letónia."],
      fr: ["Nīca est célèbre pour posséder le costume traditionnel le plus coloré de Lettonie.", "L'église luthérienne de Nīca a été consacrée en 1851.", "Le parc naturel de Bernāti jouxte directement le territoire de Nīca.", "La pêche est la principale source de revenus depuis le XVIe siècle.", "Le lac de Liepāja (Liepājas ezers) est situé juste au nord de la localité.", "Certaines des plus hautes dunes côtières de Lettonie se trouvent à proximité."],
