      hu: ["Az Usma-tó Lettország hatodik legnagyobb tava.", "A Moricsala-sziget 1912 óta természetvédelmi terület.", "A tó vízfelülete 38,89 négyzetkilométer.", "A település fatemploma 1936-ban készült el.", "A tóban hét sziget található, Moricsala a legnagyobb.", "A vidék a vitorlázás és a horgászturizmus központja."],
      ro: ["Lacul Usma este al șaselea ca mărime din Letonia.", "Rezervația Moricsala a fost înființată în anul 1912.", "Suprafața totală a lacului este de 38,89 km².", "Biserica de lemn a fost ridicată în perioada 1935–1936.", "Insula Moricsala adăpostește peste 500 de specii de plante.", "Localitatea este un nod turistic important în regiunea Kurzeme."],
      en: ["Lake Usma is the sixth largest lake in Latvia by surface area.", "Moricsala Nature Reserve was established in 1912.", "The lake features a total of seven distinct islands.", "The local wooden church was completed in 1936.", "The lake's average depth is about 5.4 meters.", "It is a major center for yachting and water sports in Courland."],
